// TestMemberOffboardDryRun verifies the --dry-run plan: prints the deactivate +
// reassign intent and exits 0 without any HTTP.
func TestMemberOffboardDryRun(t *testing.T) {
	t.Setenv("PRINTING_PRESS_VERIFY", "")
	cmd := RootCmd()
	var buf bytes.Buffer
	cmd.SetOut(&buf)
	cmd.SetErr(&buf)
	cmd.SetArgs([]string{"member", "offboard", "leaver@acme.com", "--transfer-to", "manager@acme.com", "--dry-run"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("dry-run execute error = %v", err)
	}
	out := buf.String()
	if !strings.Contains(out, "would deactivate leaver@acme.com") {
		t.Errorf("expected deactivate intent, got:\n%s", out)
	}
	if !strings.Contains(out, "reassign its files to manager@acme.com") {
		t.Errorf("expected reassign intent, got:\n%s", out)
	}
}

// TestMemberOffboardMissingTransferTo asserts the actionable error when
