func TestOwnedInodeIDs(t *testing.T) {
	entries := []map[string]any{
		{"id": "f1", "ownerId": "m1", "type": "workbook"},
		{"id": "f2", "ownerId": "other", "type": "workbook"},
		{"id": "f3", "ownerId": "m1", "type": "dataset"},
	}
	got := ownedInodeIDs(entries, "m1")
	if len(got) != 2 {
		t.Fatalf("expected 2 owned inodes, got %d: %+v", len(got), got)
	}
	want := map[string]bool{"f1": true, "f3": true}
	for _, id := range got {
		if !want[id] {
			t.Errorf("unexpected inode %q in owned set", id)
		}
	}
}

